documents.outline_text:
[
  {
    "intent": "Hook the builder with the fragility of client-attached validation sessions and introduce server-owned runs as the architectural solution.",
    "summary": "Frame the failure path where long validation suites die alongside disconnected terminals, then introduce how docs/TESTING.md establishes server-owned runs through vrooli scenario test so an agent session can detach without destroying the test's identity.",
    "target_words": 220
  },
  {
    "intent": "Explain the operational mechanics of detached suite execution and deterministic waiting without polling loops.",
    "summary": "Walk through the concrete lifecycle where test-genie assumes full ownership of the registered run identifier, enabling operators to block cleanly via test-genie runs wait --json rather than sustaining fragile client connections.",
    "target_words": 310
  },
  {
    "intent": "Distinguish between client disconnection and true test cancellation to preserve clear failure evidence.",
    "summary": "Analyze the operational boundary between dropped client sessions and explicit termination using vrooli scenario test abort, showing why separating connection drops from product defects ensures evidence remains trustworthy.",
    "target_words": 300
  },
  {
    "intent": "Conclude by demonstrating how server-owned validation enables durable asynchronous handoffs across builder workflows.",
    "summary": "Synthesize how server-owned execution turns validation into a governed background capability, allowing builders to inspect immutable test records long after client disconnection and make grounded release decisions.",
    "target_words": 250
  }
]

